import{_ as t,o as r,c as e,a2 as s}from"./chunks/framework.B2QVIpOM.js";const h=JSON.parse('{"title":"基督教崇真中学 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-8519ff16","school_zh":"基督教崇真中学","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"基督教崇真中学 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-TTCA-FIRST"],"rounds":["r1"]},"headers":[],"relativePath":"reports/school-8519ff16/s1/2022-23-interview.md","filePath":"reports/school-8519ff16/s1/2022-23-interview.md"}'),p={name:"reports/school-8519ff16/s1/2022-23-interview.md"};function a(n,o,c,l,g,i){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="基督教崇真中学-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">基督教崇真中学 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#基督教崇真中学-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;基督教崇真中学 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-8519ff16">← 返回基督教崇真中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-ttca-first" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-ttca-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-ttca-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>四个个人评估环节</strong></p><p>日常问答、中文、英文及数学四部分，由不同老师一对一面见，部分在礼堂不同桌位进行，再到课室答数学。全程反馈约35至45分钟；没有小组讨论。家长可在等候区等候。包含2023年2月的反馈。</p><p><strong>口答与现场指令</strong></p><p>部分阅读题不许在试卷写字，考生口述，由老师录入或用语音转文字记录；登记及各站使用二维码识别。结束时按黑板英文指示取回给家长的信、移除面试贴纸并丢到指定垃圾桶。</p></blockquote><blockquote><p><strong>个人问答：</strong> 中文，部分可选英语</p><p><strong>个人与校园生活</strong></p><p>在老师或父母眼中是怎样的人、如何形容班级或学校、亲子关系、周末活动、喜欢的科目、为何报读及对学校的印象；选择实体书还是iPad、网课还是面授。</p><p><strong>看图解释不同反应</strong></p><p>两幅图中，同一个人用同一句“你好漂亮”称赞两名女孩，其中一位开心，另一位反感；后一版本提到女孩脸上有痘痘。要求解释反应不同的原因、评价人物并回应追问。有学生以自信和自卑解释，这是个人作答示例。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，口语未注明</p><p><strong>阅读、词句与时限</strong></p><p>阅读后口答，部分不用朗读。版本包括约两页文章、10分钟14题（选择和短答），也有5、9或10题；一份九题限九分钟。涉及词义、修辞、成语解释、重组句子、错别字及造句。</p><p><strong>一分钟短讲</strong></p><p>介绍好朋友或最喜欢的玩具；分享首次帮助别人的经历及感受，或一次受伤经历及感受。有版本把阅读和短讲合计限十分钟。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>自我介绍与追问</strong></p><p>约一分钟介绍自己，再追问约四题或按情况延伸。题目涉及旅行及原因、家人关系、兴趣、性格、好朋友和学校老师；健康生活的三个条件，以及理想学校和怎样实现。</p><p><strong>朗读、理解和语法</strong></p><p>朗读文章后问答，题量有6、8或约10题；部分结合时态和语法选择题，六题版本中只有两题直接关于文章。另有学生只朗读、没有后续阅读问题。</p></blockquote><blockquote><p><strong>数学：</strong> 部分题目中英双语；其余未注明</p><p><strong>限时心算</strong></p><p>多份为五分钟十题，也有十一题、或十分钟十题版本。含选择、列式应用及问答，主要涉及六年级程度的分数、小数及小数乘法、面积、立体图形的顶点和棱等。</p></blockquote>',13)])])}const _=t(p,[["render",a]]);export{h as __pageData,_ as default};
